<?php
$q=$pdo->prepare('SELECT * FROM hr_requests WHERE user_id=? AND kind=? AND start_date<=? AND end_date>=? ORDER BY id DESC');$q->execute([$owner,$requestKind,$requestTo,$requestFrom]);$requests=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<section class="panel"><h2><?=$requestKind==='leave'?'My leave applications':'Attendance requests'?></h2><p>Requests overlapping the selected period. Updates also appear in your notifications.</p>
<div class="ess-request-grid"><?php foreach($requests as $r):?><article class="ess-request-item"><div class="ess-section-heading"><h3><?=h($r['subject'])?></h3><span class="badge status-<?=strtolower(h($r['status']))?>"><?=h($r['status'])?></span></div><p><?=h($r['category'])?> · <?=h($r['start_date'])?> → <?=h($r['end_date'])?></p><p><?=nl2br(h($r['details']))?></p>
<?php if($requestKind==='leave'){$workflow=ess_workflow($pdo,(int)$r['id']);if($workflow){?><p>Approvers: <?=h(implode(' → ',array_column($workflow['values']['approvers'],'name')))?></p><?php foreach($workflow['values']['decisions'] as $decision):?><p><?=h($decision['name'].' · '.$decision['status'].' · '.$decision['reason'])?></p><?php endforeach;}}?>
<?php if($r['status']==='Pending'):?><form method="post" action="employee.php?page=<?=$requestKind==='leave'?'leaves':'regularisation'?>"><?php token();?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="wide-button">Cancel request</button></form><?php endif;?></article><?php endforeach;if(!$requests):?><p class="ess-hint">No requests for this period.</p><?php endif;?></div></section>
